//! Phase 2 finalized-intent bridge: verified draft → durable funding intent.
//!
//! Adapted from predecessor paths
//! `crates/gateway/src/stage2_w5h_bridge.rs` at commit
//! `3d30617d1c13231b05e6dd5b072f471b1979eeee` and
//! `crates/gateway/src/runtime/stage2_w5h_intent_finalize_wiring.rs` at
//! commit `ade3d6e942f403bf71960acdf1880bc6a48ccf12`.
//!
//! `draft_id` is a random, non-canonical retry handle. It is generated by
//! `propose_intent`, but proposing never persists it. Only this finalize path
//! writes its consume/tombstone receipt to the bin-owned sidecar. `draft_id`
//! MUST NOT enter either the frozen draft-hash preimage or the canonical
//! `WatchRule`/rule-hash preimage.
//!
//! Persistence deliberately retains the predecessor's non-transactional
//! ordering and recovery semantics: consume draft, read market data, insert
//! WatchRule, index its hash in the independent sidecar, then insert the W5h
//! funding row. It performs no signing, transaction construction, broadcast,
//! or executor action.
//!
//! `funding_window_seconds` is descriptive metadata derived from
//! `FUNDING_WINDOW_MS`. Any signing-page countdown MUST use the absolute
//! `expires_at_ms` deadline, never reconstruct a deadline from the window
//! length. The funding row's persisted `created_at_ms` / `expires_at_ms` are
//! the sole wall-clock authority for the response and signing-page payload.

use std::{
    str::FromStr,
    time::{SystemTime, UNIX_EPOCH},
};

use claw_state_store::{
    NewW5hFundingIntent, Stage2W5hFundingIntentRepository, Stage2WatchRuleRepository, StoreError,
    W5hFundingIntent, W5hIntentStatus,
};
use claw_types::{
    canonical_rule_hash, ActionSpec, Comparison, Condition, ConditionLogic, PubkeyBytes, RateKind,
    WatchRule, STAGE2_WATCH_RULE_SCHEMA_V2,
};
use schemars::JsonSchema;
use serde::Deserialize;
use serde_json::{json, Value};
use solana_sdk::pubkey::Pubkey;
use spl_associated_token_account::get_associated_token_address;
use uuid::{Uuid, Version};

use crate::{
    finalize_market::FinalizeMarketDataSource,
    propose::{
        validate_and_hash_draft, DraftIntent, ProposeIntentParams, CONTROLLED_USDC_ATA_BS58,
        CONTROLLED_WALLET_BS58,
    },
    sidecar::{ClaimOutcome, IndexOutcome, IntentSidecar},
};

pub(crate) const USDC_MINT_BS58: &str = "EPjFWdd5AufqSSqeM2qN1xzybapC8G4wEGGkZwyTDt1v";
pub(crate) const SOLEND_RESERVE_BS58: &str = "BgxfHJDzm44T7XG68MYKx7YisTjZu73tVovyZSjJMpmw";
pub(crate) const SOLEND_LENDING_MARKET_BS58: &str = "4UpD2fh7xH3VP9QQaXtsS1YY3bxzWhtfpks7FatyKvdY";
pub(crate) const SOLEND_PROGRAM_ID_BS58: &str = "So1endDq2YkqhipRh3WViPa8hdiSpxWy6z3Z6tMCpAo";
pub(crate) const SOLEND_TARGET_OBLIGATION_BS58: &str =
    "BdFLjCcP9mCy557vNNGVbTUuvHxXsh8hc6jXzaPra1wN";
pub(crate) const MEMO_PROGRAM_ID_BS58: &str = "MemoSq4gqABAXKb96qnH8TysNcWxMyWCqXgDLGmfcHr";
pub(crate) const WATCH_RULE_EXPIRY_SLOTS: u64 = 480;
const SIGNING_PAGE_BASE_URL: &str = "http://127.0.0.1:8080/index.html";
const FUNDING_WINDOW_MS: i64 = 180_000;
const FUNDING_WINDOW_SECONDS: i64 = FUNDING_WINDOW_MS / 1_000;
const CANONICAL_DEPOSIT_MAPPING_ERROR: &str =
    "the approved draft cannot be represented as the canonical SolendDeposit action";

/// All proposal fields stay flat on the MCP wire. The two IDs have distinct
/// jobs: `draft_id` controls one-shot finalization; `draft_hash` attests the
/// canonical proposal contents. `user_wallet` is the external funding wallet,
/// resolved from the authenticated session in the predecessor and therefore
/// intentionally excluded from the earlier draft hash.
///
/// Serde documents `flatten` plus `deny_unknown_fields` as unsupported. The
/// currently locked Serde implementation does reject unknown fields for this
/// exact shape; `finalize_params_reject_unknown_fields` is the upgrade guard.
#[derive(Debug, Clone, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub(crate) struct FinalizeIntentParams {
    #[serde(flatten)]
    pub(crate) proposal: ProposeIntentParams,
    /// Random v4 UUID returned by propose_intent. Never part of a hash.
    pub(crate) draft_id: String,
    /// Canonical draft hash returned by propose_intent.
    pub(crate) draft_hash: String,
    /// Public key of the Phantom wallet that will fund the controlled ATA.
    pub(crate) user_wallet: String,
}

pub(crate) trait FinalizeClock: Send + Sync {
    fn now_ms(&self) -> i64;
}

#[derive(Debug, Clone, Copy)]
pub(crate) struct SystemFinalizeClock;

impl FinalizeClock for SystemFinalizeClock {
    fn now_ms(&self) -> i64 {
        let millis = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .expect("system clock must be after the Unix epoch")
            .as_millis();
        i64::try_from(millis).unwrap_or(i64::MAX)
    }
}

#[derive(Debug, thiserror::Error)]
pub(crate) enum FinalizeInternalError {
    #[error("state-store operation failed")]
    StateStore(#[source] StoreError),
}

/// Execute the finalized-draft bridge.
///
/// Hash mismatch and all expected fail-closed conditions are normal JSON
/// results. Only an actual main state-store failure is promoted to MCP error by
/// the caller.
pub(crate) async fn finalize_intent_json<S, C>(
    params: &FinalizeIntentParams,
    market_source: Option<&S>,
    sidecar: &IntentSidecar,
    watch_rules: &Stage2WatchRuleRepository,
    funding_intents: &Stage2W5hFundingIntentRepository,
    clock: &C,
) -> Result<Value, FinalizeInternalError>
where
    S: FinalizeMarketDataSource,
    C: FinalizeClock,
{
    let (draft, recomputed_hash) = match validate_and_hash_draft(&params.proposal) {
        Ok(validated) => validated,
        Err(error) => {
            return Ok(json!({
                "status": "invalid_input",
                "reason": error.to_string(),
            }));
        }
    };

    if recomputed_hash != params.draft_hash {
        return Ok(json!({
            "status": "hash_mismatch",
            "draft_id": params.draft_id,
            "expected_draft_hash": recomputed_hash,
            "provided_draft_hash": params.draft_hash,
            "database_writes": 0,
        }));
    }

    if !is_v4_uuid(&params.draft_id) {
        return Ok(json!({
            "status": "invalid_input",
            "reason": "draft_id must be a random UUID v4 returned by propose_intent",
        }));
    }

    // Fail before claiming the draft or touching the network/main database if
    // a future proposal shape cannot be represented by the reviewed v2 action.
    if let Err(reason) = validate_canonical_solend_deposit_draft(&draft) {
        return Ok(json!({
            "status": "canonical_action_unsupported",
            "reason": reason,
            "draft_consumed": false,
            "database_writes": 0,
        }));
    }

    // These are MCP-only preconditions. The predecessor received an already
    // authenticated session wallet and could only start with market wiring
    // present, so consuming a draft for either failure would invent a new
    // destructive behavior rather than preserve a legacy one.
    let Some(market_source) = market_source else {
        return Ok(json!({
            "status": "config_missing",
            "reason": "SOLFRONTIER_RPC_URL is not set",
            "setup": "Set SOLFRONTIER_RPC_URL in the server environment, restart, then retry finalize with the same unconsumed draft_id",
            "draft_consumed": false,
        }));
    };
    let user_wallet = match Pubkey::from_str(params.user_wallet.trim()) {
        Ok(wallet) => wallet,
        Err(_) => {
            return Ok(json!({
                "status": "invalid_user_wallet",
                "reason": "user_wallet must be a valid Solana public key",
                "draft_consumed": false,
            }));
        }
    };
    let usdc_mint = Pubkey::from_str(USDC_MINT_BS58).expect("hard-coded USDC mint must parse");
    let user_usdc_ata = get_associated_token_address(&user_wallet, &usdc_mint);

    // Once the MCP-only preconditions pass, preserve the predecessor's
    // consume-before-network-read ordering. A later market or persistence
    // failure requires a freshly proposed draft; the tombstone is not rolled
    // back.
    let draft_consumed_at_ms = clock.now_ms();
    match sidecar
        .claim_draft(&params.draft_id, &params.draft_hash, draft_consumed_at_ms)
        .await
    {
        ClaimOutcome::Claimed => {}
        ClaimOutcome::AlreadyConsumed => {
            return Ok(json!({
                "status": "already_finalized_or_missing",
                "draft_id": params.draft_id,
            }));
        }
        ClaimOutcome::Conflict => {
            return Ok(json!({
                "status": "draft_id_conflict",
                "draft_id": params.draft_id,
                "reason": "draft_id is already bound to a different draft hash",
            }));
        }
        ClaimOutcome::Unavailable => {
            return Ok(json!({
                "status": "sidecar_unavailable",
                "reason": "the local finalize index is unavailable; no main database row was written",
            }));
        }
    }

    // Preserve the predecessor's pre-market clock sample so this authority fix
    // does not shift the persisted deadline's generation order or value. The
    // sample is deliberately not a response deadline source.
    let _finalize_started_at_ms = clock.now_ms();
    let snapshot = match market_source.fetch_snapshot().await {
        Ok(snapshot) => snapshot,
        Err(error) => {
            return Ok(json!({
                "status": "market_data_error",
                "error_class": error.category(),
                "reason": error.to_string(),
                "draft_consumed": true,
            }));
        }
    };

    let fresh_rule = match build_watch_rule(&draft, snapshot.last_checked_slot) {
        Ok(rule) => rule,
        Err(reason) => {
            return Ok(json!({
                "status": "canonical_action_unsupported",
                "reason": reason,
                "draft_consumed": true,
                "database_writes": 0,
            }));
        }
    };
    let (rule_for_identity, rule_persisted) =
        persist_rule_with_legacy_recovery(watch_rules, &fresh_rule).await;
    let expected_rule = build_watch_rule(&draft, rule_for_identity.created_at_slot)
        .expect("draft was prevalidated");
    if rule_persisted && rule_for_identity != expected_rule {
        return Ok(json!({
            "status": "existing_rule_conflict",
            "draft_id": params.draft_id,
            "reason": "the persisted WatchRule with this deterministic id does not match the approved canonical SolendDeposit rule shape",
            "draft_consumed": true,
        }));
    }
    let Some(canonical_amount_raw) = canonical_solend_deposit_amount_raw(&rule_for_identity) else {
        return Ok(json!({
            "status": "existing_rule_conflict",
            "draft_id": params.draft_id,
            "reason": "the persisted WatchRule violates the exact SolendDeposit action/rule amount invariant",
            "draft_consumed": true,
        }));
    };
    let intent_id = hex_lower(&rule_for_identity.rule_id);
    let rule_hash = hex_lower(&canonical_rule_hash(&rule_for_identity));

    // The hash index is derivative and cannot make the main DB authoritative.
    // Index only a rule confirmed through the public repository API. Failure
    // degrades future hash lookup to unsupported_ref but does not change the
    // predecessor's two main-row write semantics.
    if rule_persisted {
        match sidecar
            .index_hash(
                &rule_hash,
                &intent_id,
                &params.draft_id,
                &params.draft_hash,
                clock.now_ms(),
            )
            .await
        {
            IndexOutcome::Indexed | IndexOutcome::AlreadyPresent => {}
            IndexOutcome::Conflict | IndexOutcome::Unavailable => {
                tracing::warn!(
                    operation = "index finalized intent hash",
                    "finalize sidecar hash index unavailable; UUID lookup remains authoritative"
                );
            }
        }
    }

    // Preserve the predecessor's DB deadline semantics: the 180-second funding
    // window starts when the funding row is persisted, after market reads.
    // Unlike the predecessor DTO, every response below reads its timestamps
    // from that authoritative row.
    let persisted_created_at_ms = clock.now_ms();
    let persisted_expires_at_ms = persisted_created_at_ms.saturating_add(FUNDING_WINDOW_MS);
    let new_intent = NewW5hFundingIntent {
        intent_id: intent_id.clone(),
        rule_id_hex: intent_id.clone(),
        canonical_rule_hash_hex: rule_hash.clone(),
        user_wallet: user_wallet.to_string(),
        user_usdc_ata: user_usdc_ata.to_string(),
        controlled_wallet: CONTROLLED_WALLET_BS58.to_string(),
        controlled_usdc_ata: CONTROLLED_USDC_ATA_BS58.to_string(),
        amount_raw: canonical_amount_raw,
        threshold_bps: draft.threshold_bps,
        save_display_apy_bps_at_creation: snapshot.save_display_apy_bps,
        native_onchain_apr_bps_at_creation: snapshot.native_onchain_apr_bps,
        created_at_ms: persisted_created_at_ms,
        expires_at_ms: persisted_expires_at_ms,
    };

    let persistence = persist_funding_with_legacy_recovery(funding_intents, &new_intent).await?;
    let reused_existing_intent = matches!(persistence, FundingPersistOutcome::Existing(_));
    let current = persistence.into_row();
    if let Some(response) = unconfirmed_rule_guard(
        rule_persisted,
        params,
        &intent_id,
        &rule_hash,
        current.status.as_str(),
        reused_existing_intent,
    ) {
        return Ok(response);
    }
    if !funding_row_matches_identity(&current, &rule_for_identity, &intent_id, &rule_hash) {
        return Ok(json!({
            "status": "existing_intent_conflict",
            "draft_id": params.draft_id,
            "intent_id": intent_id,
            "reason": "the authoritative funding row does not match the persisted WatchRule; no funding instructions were issued",
            "draft_consumed": true,
        }));
    }

    let response_created_at_ms = current.created_at_ms;
    let response_expires_at_ms = current.expires_at_ms;
    let memo = format!("claw:w5h:{intent_id}:{rule_hash}");
    let request_wallet_matches_persisted = current.user_wallet == user_wallet.to_string();
    if reused_existing_intent && !request_wallet_matches_persisted {
        return Ok(json!({
            "status": "existing_intent_conflict",
            "draft_id": params.draft_id,
            "intent_id": intent_id,
            "persisted_status": current.status.as_str(),
            "reason": "this deterministic intent id is already bound to a different funding wallet; no funding instructions were issued",
            "draft_consumed": true,
        }));
    }
    // Re-check immediately before producing an actionable handoff so a market
    // read cannot bridge an existing intent across its persisted deadline.
    // The endpoint is inclusive: now >= expires_at_ms is expired.
    let actionability_checked_at_ms = clock.now_ms();
    if current.status != W5hIntentStatus::FundingRequired
        || current.expires_at_ms <= actionability_checked_at_ms
    {
        let reason = if current.expires_at_ms <= actionability_checked_at_ms {
            "the persisted funding deadline has elapsed; no funding instructions were issued"
        } else {
            "the persisted intent has already advanced beyond funding_required; no funding instructions were issued"
        };
        return Ok(json!({
            "status": current.status.as_str(),
            "draft_id": params.draft_id,
            "intent_id": intent_id,
            "rule_hash": rule_hash,
            "reused_existing_intent": reused_existing_intent,
            "funding_actionable": false,
            "created_at_ms": current.created_at_ms,
            "expires_at_ms": current.expires_at_ms,
            "reason": reason,
            "draft_consumed": true,
        }));
    }

    let funding = json!({
        "user_wallet": current.user_wallet,
        "user_usdc_ata": current.user_usdc_ata,
        "controlled_wallet": current.controlled_wallet,
        "controlled_usdc_ata": current.controlled_usdc_ata,
        "mint": USDC_MINT_BS58,
        "decimals": 6,
        "amount_raw": current.amount_raw.to_string(),
        "memo": memo,
        "memo_program_id": MEMO_PROGRAM_ID_BS58,
        "instruction_order": ["memo", "transfer_checked"],
        "funding_window_seconds": FUNDING_WINDOW_SECONDS,
        "expires_at_ms": response_expires_at_ms,
    });
    let signing_page_url =
        build_signing_page_url(current.status.as_str(), &intent_id, &rule_hash, &funding);

    Ok(json!({
        "status": current.status.as_str(),
        "draft_id": params.draft_id,
        "draft_hash": params.draft_hash,
        "intent_id": intent_id,
        "rule_hash": rule_hash,
        "rule_persisted": rule_persisted,
        "reused_existing_intent": reused_existing_intent,
        "funding_actionable": true,
        "created_at_ms": response_created_at_ms,
        "expires_at_ms": response_expires_at_ms,
        "funding": funding,
        "signing_page_url": signing_page_url,
        "signing": {
            "required": true,
            "performed_by_server": false,
            "request_wallet_matches_persisted": request_wallet_matches_persisted,
            "note": "The connected Phantom wallet must equal funding.user_wallet. This MCP server never signs.",
        },
    }))
}

fn build_signing_page_url(
    status: &str,
    intent_id: &str,
    rule_hash: &str,
    funding: &Value,
) -> String {
    let payload = json!({
        "status": status,
        "funding_actionable": true,
        "intent_id": intent_id,
        "rule_hash": rule_hash,
        "funding": funding,
    });
    let encoded_payload = percent_encode_fragment_component(&payload.to_string());
    format!("{SIGNING_PAGE_BASE_URL}#payload={encoded_payload}")
}

fn percent_encode_fragment_component(value: &str) -> String {
    const HEX: &[u8; 16] = b"0123456789ABCDEF";

    let mut encoded = String::with_capacity(value.len().saturating_mul(3));
    for &byte in value.as_bytes() {
        if byte.is_ascii_alphanumeric() || matches!(byte, b'-' | b'_' | b'.' | b'~') {
            encoded.push(char::from(byte));
        } else {
            encoded.push('%');
            encoded.push(char::from(HEX[usize::from(byte >> 4)]));
            encoded.push(char::from(HEX[usize::from(byte & 0x0f)]));
        }
    }
    encoded
}

fn unconfirmed_rule_guard(
    rule_persisted: bool,
    params: &FinalizeIntentParams,
    intent_id: &str,
    rule_hash: &str,
    persisted_funding_status: &str,
    reused_existing_intent: bool,
) -> Option<Value> {
    (!rule_persisted).then(|| {
        json!({
            "status": "rule_unconfirmed",
            "draft_id": params.draft_id,
            "draft_hash": params.draft_hash,
            "intent_id": intent_id,
            "rule_hash": rule_hash,
            "rule_persisted": false,
            "funding_intent_persisted": true,
            "persisted_funding_status": persisted_funding_status,
            "reused_existing_intent": reused_existing_intent,
            "funding_actionable": false,
            "draft_consumed": true,
            "reason": "the monitoring rule could not be confirmed; funding now would be stranded pending manual refund, so no funding instructions were issued",
        })
    })
}

fn validate_canonical_solend_deposit_draft(draft: &DraftIntent) -> Result<(), &'static str> {
    if draft.action != "deposit"
        || draft.protocol != "solend"
        || draft.asset != "USDC"
        || draft.display_source != "save"
        || draft.comparison != "gt"
        || draft.expiry_seconds_after_finalize != 180
        || draft.controlled_wallet != CONTROLLED_WALLET_BS58
        || draft.controlled_usdc_ata != CONTROLLED_USDC_ATA_BS58
    {
        return Err(CANONICAL_DEPOSIT_MAPPING_ERROR);
    }
    Ok(())
}

pub(crate) fn build_watch_rule(
    draft: &DraftIntent,
    last_checked_slot: u64,
) -> Result<WatchRule, &'static str> {
    validate_canonical_solend_deposit_draft(draft)?;

    let controlled = PubkeyBytes::from_base58(CONTROLLED_WALLET_BS58)
        .expect("hard-coded controlled wallet must parse");
    let reserve =
        PubkeyBytes::from_base58(SOLEND_RESERVE_BS58).expect("hard-coded reserve must parse");
    let lending_market = PubkeyBytes::from_base58(SOLEND_LENDING_MARKET_BS58)
        .expect("hard-coded lending market must parse");
    let solend_program_id = PubkeyBytes::from_base58(SOLEND_PROGRAM_ID_BS58)
        .expect("hard-coded Solend program id must parse");
    let input_mint =
        PubkeyBytes::from_base58(USDC_MINT_BS58).expect("hard-coded USDC mint must parse");
    let target_obligation = PubkeyBytes::from_base58(SOLEND_TARGET_OBLIGATION_BS58)
        .expect("hard-coded target obligation must parse");
    let input_amount_raw = draft.amount_raw;

    Ok(WatchRule {
        // PR-C closes the predecessor's first-class action gap: finalized
        // deposits now bind all six execution inputs in schema v2.
        schema_version: STAGE2_WATCH_RULE_SCHEMA_V2,
        rule_id: derive_rule_id(draft.threshold_bps, draft.amount_raw, &controlled),
        user: controlled,
        executor: controlled,
        delegated_wallet: controlled,
        created_at_slot: last_checked_slot,
        expires_at_slot: last_checked_slot.saturating_add(WATCH_RULE_EXPIRY_SLOTS),
        one_shot: true,
        condition_logic: ConditionLogic::All,
        conditions: vec![Condition::SolendReserveSupplyRate {
            reserve_pubkey: reserve,
            lending_market,
            solend_program_id,
            comparison: Comparison::Gt,
            threshold_bps: draft.threshold_bps,
            rate_kind: RateKind::Apr,
            formula_version: 1,
            max_reserve_staleness_slots: 16,
            required_refresh_same_tx: true,
        }],
        action: ActionSpec::SolendDeposit {
            target_obligation,
            reserve_pubkey: reserve,
            lending_market,
            solend_program_id,
            input_mint,
            input_amount_raw,
        },
        max_input_amount_raw: input_amount_raw,
        used_amount_raw: 0,
        destination: controlled,
        slippage_bps: 0,
    })
}

fn derive_rule_id(
    threshold_bps: u32,
    amount_raw: u64,
    controlled_wallet: &PubkeyBytes,
) -> [u8; 16] {
    let mut rule_id = [0_u8; 16];
    rule_id[0..4].copy_from_slice(&threshold_bps.to_le_bytes());
    rule_id[4..12].copy_from_slice(&amount_raw.to_le_bytes());
    rule_id[12..16].copy_from_slice(&controlled_wallet.0[0..4]);
    rule_id
}

async fn persist_rule_with_legacy_recovery(
    repository: &Stage2WatchRuleRepository,
    fresh: &WatchRule,
) -> (WatchRule, bool) {
    match repository.insert(fresh).await {
        Ok(()) => (fresh.clone(), true),
        Err(_) => match repository.get(&fresh.rule_id).await {
            Ok(Some(stored)) => (stored.rule, true),
            // Deliberately retained legacy flaw: a failed insert plus a
            // failed/missing readback still proceeds to the funding write.
            Ok(None) | Err(_) => (fresh.clone(), false),
        },
    }
}

enum FundingPersistOutcome {
    Inserted(W5hFundingIntent),
    Existing(W5hFundingIntent),
}

impl FundingPersistOutcome {
    fn into_row(self) -> W5hFundingIntent {
        match self {
            Self::Inserted(row) | Self::Existing(row) => row,
        }
    }
}

async fn persist_funding_with_legacy_recovery(
    repository: &Stage2W5hFundingIntentRepository,
    fresh: &NewW5hFundingIntent,
) -> Result<FundingPersistOutcome, FinalizeInternalError> {
    match repository.insert(fresh).await {
        Ok(()) => match repository.get(&fresh.intent_id).await {
            Ok(Some(persisted)) => Ok(FundingPersistOutcome::Inserted(persisted)),
            Ok(None) => Err(FinalizeInternalError::StateStore(StoreError::NotFound {
                entity: "stage2_w5h_funding_intents".to_owned(),
                id: fresh.intent_id.clone(),
            })),
            Err(read_error) => Err(FinalizeInternalError::StateStore(read_error)),
        },
        Err(insert_error) => match repository.get(&fresh.intent_id).await {
            Ok(Some(existing)) => Ok(FundingPersistOutcome::Existing(existing)),
            Ok(None) => Err(FinalizeInternalError::StateStore(insert_error)),
            Err(read_error) => Err(FinalizeInternalError::StateStore(read_error)),
        },
    }
}

fn funding_row_matches_identity(
    funding: &W5hFundingIntent,
    rule: &WatchRule,
    intent_id: &str,
    rule_hash: &str,
) -> bool {
    if funding.intent_id != intent_id
        || funding.rule_id_hex != intent_id
        || !funding
            .canonical_rule_hash_hex
            .eq_ignore_ascii_case(rule_hash)
        || funding.controlled_wallet != CONTROLLED_WALLET_BS58
        || funding.controlled_usdc_ata != CONTROLLED_USDC_ATA_BS58
        || !has_exact_solend_deposit_amount_invariant(rule, funding.amount_raw)
    {
        return false;
    }

    let Some(rule_threshold_bps) = rule
        .conditions
        .first()
        .and_then(|condition| match condition {
            Condition::SolendReserveSupplyRate { threshold_bps, .. } => Some(*threshold_bps),
            _ => None,
        })
    else {
        return false;
    };
    if funding.threshold_bps != rule_threshold_bps {
        return false;
    }

    let Ok(user_wallet) = Pubkey::from_str(&funding.user_wallet) else {
        return false;
    };
    get_associated_token_address(
        &user_wallet,
        &Pubkey::from_str(USDC_MINT_BS58).expect("hard-coded USDC mint must parse"),
    )
    .to_string()
        == funding.user_usdc_ata
}

fn canonical_solend_deposit_amount_raw(rule: &WatchRule) -> Option<u64> {
    match &rule.action {
        ActionSpec::SolendDeposit {
            input_amount_raw, ..
        } if *input_amount_raw == rule.max_input_amount_raw => Some(*input_amount_raw),
        _ => None,
    }
}

fn has_exact_solend_deposit_amount_invariant(rule: &WatchRule, funding_amount_raw: u64) -> bool {
    canonical_solend_deposit_amount_raw(rule) == Some(funding_amount_raw)
}

fn is_v4_uuid(value: &str) -> bool {
    Uuid::parse_str(value)
        .ok()
        .is_some_and(|id| id.get_version() == Some(Version::Random))
}

pub(crate) fn hex_lower(bytes: &[u8]) -> String {
    use std::fmt::Write;

    let mut output = String::with_capacity(bytes.len() * 2);
    for byte in bytes {
        write!(&mut output, "{byte:02x}").expect("writing to String cannot fail");
    }
    output
}

