    static TEST_DB_SEQUENCE: AtomicU64 = AtomicU64::new(0);

    struct TempDatabaseFile {
        path: PathBuf,
    }

    impl TempDatabaseFile {
        fn unique() -> Self {
            let sequence = TEST_DB_SEQUENCE.fetch_add(1, Ordering::Relaxed);
            let path = std::env::temp_dir().join(format!(
                "solfrontier-mcp-finalize-{}-{sequence}.db",
                std::process::id()
            ));
            Self { path }
        }

        fn config(&self) -> DatabaseConfig {
            DatabaseConfig {
                path: self.path.to_string_lossy().into_owned(),
                max_connections: 1,
            }
        }
    }

    impl Drop for TempDatabaseFile {
        fn drop(&mut self) {
            let sidecar = derive_sidecar_path(&self.path);
            for path in [
                self.path.clone(),
                PathBuf::from(format!("{}-wal", self.path.display())),
                PathBuf::from(format!("{}-shm", self.path.display())),
                sidecar.clone(),
                PathBuf::from(format!("{}-journal", sidecar.display())),
                PathBuf::from(format!("{}-wal", sidecar.display())),
                PathBuf::from(format!("{}-shm", sidecar.display())),
            ] {
                let _ = fs::remove_file(path);
            }
        }
    }

    struct MockMarketSource {
        snapshots: Vec<FinalizeMarketSnapshot>,
        calls: AtomicUsize,
    }

    impl MockMarketSource {
        fn new(snapshots: Vec<FinalizeMarketSnapshot>) -> Self {
            Self {
                snapshots,
                calls: AtomicUsize::new(0),
            }
        }

        fn calls(&self) -> usize {
            self.calls.load(Ordering::SeqCst)
        }
    }

    impl FinalizeMarketDataSource for MockMarketSource {
        async fn fetch_snapshot(&self) -> Result<FinalizeMarketSnapshot, FinalizeMarketReadError> {
            let index = self.calls.fetch_add(1, Ordering::SeqCst);
            self.snapshots
                .get(index)
                .copied()
                .ok_or(FinalizeMarketReadError::SlotRequestFailed)
        }
    }

    struct StepClock {
        base_ms: i64,
        step_ms: i64,
        calls: AtomicUsize,
    }

    impl StepClock {
        fn new(base_ms: i64, step_ms: i64) -> Self {
            Self {
                base_ms,
                step_ms,
                calls: AtomicUsize::new(0),
            }
        }
    }

    impl FinalizeClock for StepClock {
        fn now_ms(&self) -> i64 {
            let index = self.calls.fetch_add(1, Ordering::SeqCst);
            self.base_ms
                .saturating_add(self.step_ms.saturating_mul(index as i64))
        }
    }

