    #[test]
    fn exact_deposit_amount_invariant_rejects_each_mismatch() {
        let rule = expected_rule();
        assert!(has_exact_solend_deposit_amount_invariant(&rule, 500_000));

        let mut wrong_action_amount = rule.clone();
        let ActionSpec::SolendDeposit {
            input_amount_raw, ..
        } = &mut wrong_action_amount.action
        else {
            panic!("fixture must be a canonical deposit");
        };
        *input_amount_raw += 1;
        assert!(!has_exact_solend_deposit_amount_invariant(
            &wrong_action_amount,
            500_000
        ));

        let mut wrong_rule_cap = rule.clone();
        wrong_rule_cap.max_input_amount_raw += 1;
        assert!(!has_exact_solend_deposit_amount_invariant(
            &wrong_rule_cap,
            500_000
        ));

        assert!(!has_exact_solend_deposit_amount_invariant(&rule, 500_001));
    }

    fn signing_page_payload(response: &Value) -> Value {
        let url = response["signing_page_url"]
            .as_str()
            .expect("actionable response must include a signing-page URL");
        let encoded = url
            .strip_prefix(SIGNING_PAGE_BASE_URL)
            .and_then(|suffix| suffix.strip_prefix("#payload="))
            .expect("signing instructions must live only in the URL fragment");
        let bytes = encoded.as_bytes();
        let mut decoded = Vec::with_capacity(bytes.len());
        let mut index = 0;
        while index < bytes.len() {
            if bytes[index] == b'%' {
                let hex = std::str::from_utf8(
                    bytes
                        .get(index + 1..index + 3)
                        .expect("percent escape must contain two hex digits"),
                )
                .expect("percent escape must be ASCII");
                decoded.push(u8::from_str_radix(hex, 16).expect("percent escape must be hex"));
                index += 3;
            } else {
                decoded.push(bytes[index]);
                index += 1;
            }
        }
        serde_json::from_slice(&decoded).expect("decoded fragment must be JSON")
    }

    #[test]
    fn finalize_params_reject_unknown_fields() {
        let valid = params_json_with_id(FIRST_DRAFT_ID);
        serde_json::from_value::<FinalizeIntentParams>(valid.clone())
            .expect("the flat wire shape must deserialize");

        let mut with_unknown = valid;
        with_unknown
            .as_object_mut()
            .expect("fixture is an object")
            .insert("unexpected_field".into(), json!(true));
        let error = serde_json::from_value::<FinalizeIntentParams>(with_unknown)
            .expect_err("unknown finalize fields must fail closed");
        let message = error.to_string();
        assert!(
            message.contains("unknown field") && message.contains("unexpected_field"),
            "unexpected deserialization error: {message}"
        );
    }

