    #[tokio::test]
    async fn same_draft_rejects_but_fresh_draft_with_same_semantics_recovers_existing_rows() {
        let (_file, db, watch_rules, funding_intents, sidecar) = test_store().await;
        let first = params_with_id(FIRST_DRAFT_ID);
        let second = params_with_id(SECOND_DRAFT_ID);
        let mut different_wallet = params_with_id(THIRD_DRAFT_ID);
        different_wallet.user_wallet = Pubkey::new_unique().to_string();
        let market = MockMarketSource::new(vec![
            snapshot(FIRST_MARKET_SLOT, 165, 210),
            snapshot(FIRST_MARKET_SLOT + 99, 999, 888),
            snapshot(FIRST_MARKET_SLOT + 199, 777, 666),
        ]);
        let clock = StepClock::new(FINALIZE_STARTED_AT_MS, CLOCK_STEP_MS);

        let first_response = finalize_intent_json(
            &first,
            Some(&market),
            &sidecar,
            &watch_rules,
            &funding_intents,
            &clock,
        )
        .await
        .expect("first finalize");
        let retry_response = finalize_intent_json(
            &first,
            Some(&market),
            &sidecar,
            &watch_rules,
            &funding_intents,
            &clock,
        )
        .await
        .expect("same-draft retry is a normal response");
        assert_eq!(retry_response["status"], "already_finalized_or_missing");
        assert_eq!(
            market.calls(),
            1,
            "same-draft rejection must happen before the market read"
        );

        let retyped_response = finalize_intent_json(
            &second,
            Some(&market),
            &sidecar,
            &watch_rules,
            &funding_intents,
            &clock,
        )
        .await
        .expect("fresh draft with identical semantics");
        assert_eq!(market.calls(), 2);
        assert_eq!(retyped_response["status"], "funding_required");
        assert_eq!(retyped_response["intent_id"], first_response["intent_id"]);
        assert_eq!(retyped_response["rule_hash"], first_response["rule_hash"]);
        assert_eq!(retyped_response["reused_existing_intent"], true);
        assert_eq!(
            retyped_response["funding"]["user_wallet"], TEST_USER_WALLET,
            "collision recovery must expose the authoritative row"
        );
        assert_eq!(
            retyped_response["signing"]["request_wallet_matches_persisted"],
            true
        );

        let rule = watch_rules
            .get(&expected_rule().rule_id)
            .await
            .expect("watch-rule lookup")
            .expect("persisted rule");
        assert_eq!(
            rule.rule.created_at_slot, FIRST_MARKET_SLOT,
            "collision recovery must use the persisted rule, not the fresh live-slot rule"
        );
        let funding = funding_intents
            .get(EXPECTED_INTENT_ID)
            .await
            .expect("funding lookup")
            .expect("persisted funding row");
        assert_eq!(funding.native_onchain_apr_bps_at_creation, 165);
        assert_eq!(funding.save_display_apy_bps_at_creation, 210);
        assert_eq!(
            retyped_response["created_at_ms"], funding.created_at_ms,
            "collision recovery must not invent a fresh funding deadline"
        );
        assert_eq!(
            retyped_response["expires_at_ms"], funding.expires_at_ms,
            "collision recovery must expose the authoritative deadline"
        );
        assert_eq!(
            retyped_response["funding"]["expires_at_ms"], funding.expires_at_ms,
            "collision funding instructions must use the persisted deadline"
        );
        assert_eq!(
            signing_page_payload(&retyped_response)["funding"]["expires_at_ms"],
            funding.expires_at_ms,
            "collision signing URLs must carry the persisted deadline verbatim"
        );

        let wallet_conflict = finalize_intent_json(
            &different_wallet,
            Some(&market),
            &sidecar,
            &watch_rules,
            &funding_intents,
            &clock,
        )
        .await
        .expect("different-wallet collision is a normal response");
        assert_eq!(market.calls(), 3);
        assert_eq!(wallet_conflict["status"], "existing_intent_conflict");
        assert_eq!(wallet_conflict["persisted_status"], "funding_required");
        assert!(
            wallet_conflict.get("funding").is_none(),
            "wallet collision must never return actionable funding instructions"
        );

        close_test_store(db, watch_rules, funding_intents, sidecar).await;
    }

    #[tokio::test]
    async fn existing_intent_at_exact_deadline_is_not_actionable() {
        let (_file, db, watch_rules, funding_intents, sidecar) = test_store().await;
        let first = params_with_id(FIRST_DRAFT_ID);
        let second = params_with_id(SECOND_DRAFT_ID);
        let market = MockMarketSource::new(vec![
            snapshot(FIRST_MARKET_SLOT, 165, 210),
            snapshot(FIRST_MARKET_SLOT + 99, 999, 888),
        ]);

        let first_clock = StepClock::new(FINALIZE_STARTED_AT_MS, CLOCK_STEP_MS);
        let first_response = finalize_intent_json(
            &first,
            Some(&market),
            &sidecar,
            &watch_rules,
            &funding_intents,
            &first_clock,
        )
        .await
        .expect("first finalize");
        let authoritative_expiry = funding_intents
            .get(EXPECTED_INTENT_ID)
            .await
            .expect("funding lookup")
            .expect("persisted funding row")
            .expires_at_ms;

        // Hold every clock read exactly on the persisted endpoint. The final
        // actionability check must treat now == expires_at_ms as expired.
        let expired_clock = StepClock::new(authoritative_expiry, 0);
        let expired_response = finalize_intent_json(
            &second,
            Some(&market),
            &sidecar,
            &watch_rules,
            &funding_intents,
            &expired_clock,
        )
        .await
        .expect("expired collision is a normal response");

        assert_eq!(first_response["funding_actionable"], true);
        assert_eq!(expired_response["status"], "funding_required");
        assert_eq!(expired_response["funding_actionable"], false);
        assert_eq!(expired_response["expires_at_ms"], authoritative_expiry);
        assert!(
            expired_response.get("funding").is_none(),
            "expired existing intent must not expose signing instructions"
        );
        assert!(
            expired_response.get("signing").is_none(),
            "an expired intent must not invite a signature"
        );
        assert!(
            expired_response.get("signing_page_url").is_none(),
            "a non-actionable intent must not expose a signing-page handoff"
        );

        close_test_store(db, watch_rules, funding_intents, sidecar).await;
    }

    #[tokio::test]
    async fn deterministic_id_collision_with_wrong_rule_shape_fails_closed() {
        let (_file, db, watch_rules, funding_intents, sidecar) = test_store().await;
        let params = params_with_id(FIRST_DRAFT_ID);
        let mut conflicting_rule = expected_rule();
        conflicting_rule.slippage_bps = 1;
        watch_rules
            .insert(&conflicting_rule)
            .await
            .expect("seed conflicting rule through the public repository");
        let market = MockMarketSource::new(vec![snapshot(FIRST_MARKET_SLOT, 165, 210)]);
        let clock = StepClock::new(FINALIZE_STARTED_AT_MS, CLOCK_STEP_MS);

        let response = finalize_intent_json(
            &params,
            Some(&market),
            &sidecar,
            &watch_rules,
            &funding_intents,
            &clock,
        )
        .await
        .expect("rule collision is a normal response");

        assert_eq!(response["status"], "existing_rule_conflict");
        assert!(
            response.get("funding").is_none(),
            "conflicting rule must never produce funding instructions"
        );
        assert!(funding_intents
            .get(EXPECTED_INTENT_ID)
            .await
            .expect("funding lookup")
            .is_none());

        close_test_store(db, watch_rules, funding_intents, sidecar).await;
    }

    #[test]
    fn watch_rule_expiry_slot_saturates_at_u64_max() {
        let proposal = valid_params();
        let (draft, _) = validate_and_hash_draft(&proposal).expect("valid proposal must hash");
        let rule = build_watch_rule(&draft, u64::MAX - 100).expect("approved draft must map to v2");

        assert_eq!(rule.created_at_slot, u64::MAX - 100);
        assert_eq!(rule.expires_at_slot, u64::MAX);
        assert_eq!(hex_lower(&rule.rule_id), EXPECTED_INTENT_ID);
    }
